import{t as e}from"./utils-COoNfFoj.js";var t={slug:`jonathan-parsons`,influencerName:`Jonathan Parsons`,influencerHandle:`@jonathanparsons`,influencerAvatarUrl:`${e}/jonathan-parsons-avatar.jpeg`,heroDescription:`As a Marketing Director in beauty, staying on top of trends is essential—but I don’t have time to scour the internet every day. So I built a tool that does it for me. I take those insights and turn them into marketing plans that truly resonate with my consumer.`,assetTitle:`Aura Intel`,screenshotUrl:`${e}/jonathan-parsons.png`,remixUrl:`https://www.perplexity.ai/computer/a/beauty-trends-tracker-2K01qgk4R.ywWScjSzBB3A`,promptTitle:`Try Jonathan's prompt`,promptText:`Build a web-based Beauty Trends Tracker and Idea Generator that continuously aggregates data from TikTok, Instagram, Reddit, Pinterest, and Sephora reviews to detect emerging beauty trends using NLP and trend clustering. Visualize insights in a real-time dashboard featuring a dynamic keyword map that highlights top trending ingredients, techniques, and themes. Include a competitor intelligence module that tracks and summarizes weekly content and product pushes from major beauty brands. Implement an automated Friday morning digest that delivers the top five high-potential content ideas each week, with each idea including a compelling hook, strategic angle, and recommended content format. Generate a detailed ideas document where each concept is paired with an AI-generated image for visual inspiration, and incorporate a forward-looking seasonal trend calendar that predicts and surfaces upcoming beauty moments at least four weeks in advance to support proactive content planning.`};export{t as default};
